import { defineType, defineField } from 'sanity';

const fileTreeItems = [{ type: 'file' }, { type: 'folder' }];

export const file = defineType({
  name: 'file',
  type: 'object',
  title: 'File',
  fields: [
    defineField({
      name: 'name',
      title: 'Name',
      type: 'string',
      validation: (r) => r.required(),
    }),
  ],
  preview: {
    select: {
      title: 'name',
    },
  },
});

export const folder = defineType({
  name: 'folder',
  type: 'object',
  title: 'Folder',
  fields: [
    defineField({
      name: 'name',
      title: 'Name',
      type: 'string',
      validation: (r) => r.required(),
    }),
    defineField({
      name: 'defaultOpen',
      title: 'Open by default',
      type: 'boolean',
      initialValue: false,
    }),
    defineField({
      name: 'items',
      title: 'Items',
      type: 'array',
      of: fileTreeItems,
    }),
  ],
  preview: {
    select: {
      title: 'name',
    },
  },
});

export const files = defineType({
  name: 'files',
  type: 'object',
  title: 'Files',
  fields: [
    defineField({
      name: 'items',
      title: 'Items',
      type: 'array',
      of: fileTreeItems,
    }),
  ],
  preview: {
    prepare() {
      return {
        title: 'File Tree',
      };
    },
  },
});

import type { PortableTextTypeComponent } from '@portabletext/react';
import { File, Files, Folder } from 'fumadocs-ui/components/files';

export interface FileValue {
  _key?: string;
  _type: 'file';
  name?: string;
}

export interface FolderValue {
  _key?: string;
  _type: 'folder';
  name?: string;
  defaultOpen?: boolean;
  items?: FileTreeItem[];
}

export interface FilesValue {
  _type: 'files';
  items?: FileTreeItem[];
}

type FileTreeItem = FileValue | FolderValue;

function renderFileTree(items: FileTreeItem[] | undefined) {
  return items?.map((item, index) => {
    const key = item._key ?? index;

    if (item._type === 'folder') {
      return (
        <Folder key={key} name={item.name ?? ''} defaultOpen={item.defaultOpen}>
          {renderFileTree(item.items)}
        </Folder>
      );
    }

    return <File key={key} name={item.name ?? ''} />;
  });
}

export const filesComponents: {
  file: PortableTextTypeComponent<FileValue>;
  folder: PortableTextTypeComponent<FolderValue>;
  files: PortableTextTypeComponent<FilesValue>;
} = {
  file({ value }) {
    return <File name={value.name ?? ''} />;
  },
  folder({ value }) {
    return (
      <Folder name={value.name ?? ''} defaultOpen={value.defaultOpen}>
        {renderFileTree(value.items)}
      </Folder>
    );
  },
  files({ value }) {
    return <Files>{renderFileTree(value.items)}</Files>;
  },
};
